import pytest

from bedrock_protocol import v975, v1001, v2225

# TODO: confirm against BDS: gophertunnel writes BoolOperation as an optional int32 (01 00000000), the dump
# name-codes it (08 "override"), so gophertunnel has to give.
# generated by gophertunnel e76ee66:
# &packet.ClientBoundAttributeLayerSync{PayloadType: protocol.AttributeLayerPayloadTypeUpdateEnvironment,
# LayerName: "wet", EnvironmentAttributes: []protocol.EnvironmentAttributeData{{AttributeName: "temp",
# Attribute: protocol.AttributeData{Type: protocol.AttributeDataTypeBool, BoolValue: true,
# BoolOperation: protocol.Option[int32](protocol.AttributeBoolOperationOverride)}}}}
V975 = bytes.fromhex(
    "020377657400010474656d70000001"
    "086f76657272696465"  # TODO: patched, confirm against BDS
    "000000000000000000066c696e656172"
)

# generated by gophertunnel 6353c49:
# &packet.ClientBoundAttributeLayerSync{PayloadType: protocol.AttributeLayerPayloadTypeUpdateEnvironment,
# LayerName: "wet", EnvironmentAttributes: []protocol.EnvironmentAttributeData{{AttributeName: "temp",
# Attribute: protocol.AttributeData{Type: protocol.AttributeDataTypeBool, BoolValue: true,
# BoolOperation: protocol.Option[int32](protocol.AttributeBoolOperationOverride)}}}}
V1001 = bytes.fromhex("020377657400010474656d70000001086f76657272696465000000000000000000066c696e6561720000000000")

GOLDENS = [
    pytest.param(
        v975.ClientboundAttributeLayerSyncPacket(
            data=v975.UpdateEnvironmentAttributesData(
                layer_name="wet",
                layer_dimension_id=0,
                attributes=[
                    v975.EnvironmentAttributeData(
                        name="temp",
                        attribute=v975.BoolAttributeData(value=True, operation=v975.BoolAttributeOperation.OVERRIDE),
                        current_transition_ticks=0,
                        total_transition_ticks=0,
                        easing=v975.EasingType.LINEAR,
                    )
                ],
            )
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.ClientboundAttributeLayerSyncPacket(
            data=v1001.UpdateEnvironmentAttributesData(
                layer_name="wet",
                layer_dimension_id=0,
                attributes=[
                    v1001.EnvironmentAttributeData(
                        name="temp",
                        attribute=v1001.BoolAttributeData(value=True, operation=v1001.BoolAttributeOperation.OVERRIDE),
                        current_transition_ticks=0,
                        total_transition_ticks=0,
                        easing=v1001.EasingType.LINEAR,
                        local_transition_ticks=0,
                        noise_transition=False,
                    )
                ],
            )
        ),
        V1001,
        id="v1001",
    ),
]

CONSTANT = v2225.ConstantAttributeData(
    attribute=v2225.BoolAttributeData(value=True, operation=v2225.BoolAttributeOperation.OVERRIDE)
)

LINEAR_SETTINGS = v2225.TransitionSettingsData(
    total_transition_ticks=40, current_transition_ticks=10, easing=v2225.EasingType.LINEAR, clock_name="day"
)

BOUNCY_SETTINGS = v2225.TransitionSettingsData(
    total_transition_ticks=40, current_transition_ticks=10, easing=v2225.EasingType.IN_OUT_BOUNCE, clock_name="day"
)

TRANSITION = v2225.TransitionAttributeData(
    from_attribute=v2225.BoolAttributeData(value=False, operation=v2225.BoolAttributeOperation.OVERRIDE),
    to_attribute=v2225.BoolAttributeData(value=True, operation=v2225.BoolAttributeOperation.OVERRIDE),
    settings=LINEAR_SETTINGS,
)

NOISE = v2225.NoiseTransitionAttributeData(
    from_attribute=v2225.BoolAttributeData(value=False, operation=v2225.BoolAttributeOperation.OVERRIDE),
    to_attribute=v2225.BoolAttributeData(value=True, operation=v2225.BoolAttributeOperation.OVERRIDE),
    settings=v2225.NoiseTransitionSettingsData(
        total_transition_ticks=40,
        current_transition_ticks=10,
        easing=v2225.EasingType.LINEAR,
        clock_name="day",
        local_transition_ticks=5,
        noise_name="gust",
        noise_alignment=v2225.NoiseAlignment(type=v2225.NoiseAlignmentType.MIN_LOCAL_TRANSITION_END, value=3),
    ),
)


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_attribute_layer_sync_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_attribute_layer_sync_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("payload", [CONSTANT, TRANSITION, NOISE], ids=["constant", "transition", "noise-transition"])
def test_2225_round_trips_each_attribute_payload(payload):
    packet = v2225.ClientboundAttributeLayerSyncPacket(
        data=v2225.UpdateEnvironmentAttributesData(
            layer_name="wet",
            layer_dimension_id=0,
            attributes=[v2225.EnvironmentAttributeData(name="temp", payload=payload)],
        )
    )
    assert v2225.ClientboundAttributeLayerSyncPacket.from_bytes(bytes(packet)) == packet


def test_2225_int_codes_linear_and_bounce_to_the_same_width():
    assert len(bytes(LINEAR_SETTINGS)) == len(bytes(BOUNCY_SETTINGS))


def test_2225_int_codes_the_easing_as_its_own_bytes():
    assert bytes(LINEAR_SETTINGS) != bytes(BOUNCY_SETTINGS)


def test_2225_round_trips_an_easing_the_flat_shape_name_coded():
    assert v2225.TransitionSettingsData.from_bytes(bytes(BOUNCY_SETTINGS)) == BOUNCY_SETTINGS
